1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.util.Collection;
15	import java.util.List;
16	import java.util.Locale;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    /** Fixed city-to-region table used to derive an owner's region. */
25	    java.util.Map<String, String> CITY_REGION =
26	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials", expression = "java(initials(owner))")
31	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
32	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(locality(owner))")
37	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
38	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * The owner's age band, derived from the supplied birthDate as at the
43	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18-64, and 'SENIOR' when
44	     * 65 or older. Returns {@code null} when no birthDate (or registrationDate) is
45	     * available, so the field is omitted for owners without a supplied birth date.
46	     */
47	    default String ageBand(Owner owner) {
48	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
49	            return null;
50	        }
51	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
52	        if (age < 18) {
53	            return "MINOR";
54	        }
55	        if (age < 65) {
56	            return "ADULT";
57	        }
58	        return "SENIOR";
59	    }
60	
61	    /**
62	     * The owner's preferred contact channel: 'EMAIL' when an email address is present,
63	     * otherwise 'PHONE'.
64	     */
65	    default String contactPreference(Owner owner) {
66	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
67	        return hasEmail ? "EMAIL" : "PHONE";
68	    }
69	
70	    /**
71	     * The owner's region, read from the {@code <REGION>-<HASH8>} customer code assigned on
72	     * creation: the segment before the first '-'. Returns 'UNKNOWN' when no customer code has
73	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
74	     */
75	    default String locality(Owner owner) {
76	        String code = owner.getCustomerCode();
77	        if (code != null) {
78	            int dash = code.indexOf('-');
79	            if (dash > 0) {
80	                return code.substring(0, dash);
81	            }
82	        }
83	        return "UNKNOWN";
84	    }
85	
86	    /**
87	     * The owner's numeric membership level, assigned on creation. It starts at 1, gains
88	     * 1 when an email address is present, and gains 1 when the owner has no namesakes
89	     * (namesakeCount is 0), capped at 3. Level 4 is reserved for tenure.
90	     */
91	    default Integer membershipLevel(Owner owner) {
92	        int level = 1;
93	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
94	        if (hasEmail) {
95	            level++;
96	        }
97	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
98	        if (noNamesakes) {
99	            level++;
100	        }
101	        return Math.min(level, 3);
102	    }
103	
104	    /**
105	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
106	     * customerCode. Returns {@code null} when the customerCode has not been assigned.
107	     */
108	    default Integer checkDigit(Owner owner) {
109	        if (owner.getCustomerCode() == null) {
110	            return null;
111	        }
112	        String s = owner.getCustomerCode();
113	        int sum = 0;
114	        boolean dbl = true;
115	        for (int i = s.length() - 1; i >= 0; i--) {
116	            char c = s.charAt(i);
117	            if (c < '0' || c > '9') {
118	                continue;
119	            }
120	            int d = c - '0';
121	            if (dbl) {
122	                d *= 2;
123	                if (d > 9) {
124	                    d -= 9;
125	                }
126	            }
127	            sum += d;
128	            dbl = !dbl;
129	        }
130	        return (10 - (sum % 10)) % 10;
131	    }
132	
133	    /**
134	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY
135	     * is the last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
136	     */
137	    default String membershipNumber(Owner owner) {
138	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
139	            return null;
140	        }
141	        return String.format("%s-M%02d", owner.getCustomerCode(),
142	            owner.getRegistrationDate().getYear() % 100);
143	    }
144	
145	    /**
146	     * The upper-cased first letters of firstName and lastName, dot-separated with a
147	     * trailing dot, e.g. 'J.S.'.
148	     */
149	    default String initials(Owner owner) {
150	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
151	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
152	    }
153	
154	    /**
155	     * A stable identifier for the owner's household, derived deterministically from the
156	     * normalized last name and the postcode. Every owner sharing the same last name
157	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
158	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
159	     * '&lt;normalizedLastName&gt;|&lt;postcode&gt;'. A {@code null} postcode contributes
160	     * the empty string.
161	     */
162	    default String householdId(Owner owner) {
163	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
164	        String key = normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
165	        try {
166	            byte[] digest = MessageDigest.getInstance("SHA-256")
167	                .digest(key.getBytes(StandardCharsets.UTF_8));
168	            StringBuilder sb = new StringBuilder();
169	            for (int i = 0; i < 6; i++) {
170	                sb.append(String.format("%02X", digest[i]));
171	            }
172	            return sb.toString();
173	        }
174	        catch (java.security.NoSuchAlgorithmException e) {
175	            throw new IllegalStateException(e);
176	        }
177	    }
178	
179	    /**
180	     * The owner's derived identity key: the single value onto which all duplicate
181	     * detection is consolidated, formatted
182	     * '&lt;normalizedTelephone&gt;|&lt;email or empty&gt;|&lt;householdId&gt;'.
183	     * The telephone and email are the owner's stored (already normalized) values;
184	     * a {@code null} email contributes the empty string. Two owners are duplicates
185	     * only when their whole identity keys are equal.
186	     */
187	    default String identityKey(Owner owner) {
188	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
189	        String email = owner.getEmail() == null ? "" : owner.getEmail();
190	        return telephone + "|" + email + "|" + householdId(owner);
191	    }
192	
193	    private static String normalizeHouseholdKey(String value) {
194	        if (value == null) {
195	            return "";
196	        }
197	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
198	    }
199	
200	    Owner toOwner(OwnerDto ownerDto);
201	
202	    @Mapping(target = "id", ignore = true)
203	    @Mapping(target = "pets", ignore = true)
204	    Owner toOwner(OwnerFieldsDto ownerDto);
205	
206	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
207	
208	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
209	
210	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
211	        OwnerPageDto ownerPageDto = new OwnerPageDto();
212	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
213	        ownerPageDto.setPage(ownerPage.getNumber());
214	        ownerPageDto.setSize(ownerPage.getSize());
215	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
216	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
217	        return ownerPageDto;
218	    }
219	}
