58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger for owner lifecycle side-effects. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /**
70	     * Pragmatic check for a syntactically valid email address: a non-empty local
71	     * part, a single '@', and a domain with at least one dot-separated label.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization,
78	     * keyed by their upper-cased form.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
81	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
82	
83	    /**
84	     * Required national-number length keyed by E.164 country calling code: a
85	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
86	     * (NANP) number carries 10. A number whose country code is listed here must have
87	     * exactly the mandated number of national digits.
88	     */
89	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
90	        Map.of("61", 9, "1", 10);
91	
92	    /**
93	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
94	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
95	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
96	     * postcode.
97	     */
98	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
99	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
100	            "QLD", new int[] {4000, 4099});
101	
102	    private final ClinicService clinicService;
103	
104	    private final OwnerMapper ownerMapper;
105	
106	    private final PetMapper petMapper;
107	
108	    private final VisitMapper visitMapper;
109	
110	    public OwnerRestControllerV1(ClinicService clinicService,
111	                                 OwnerMapper ownerMapper,
112	                                 PetMapper petMapper,
113	                                 VisitMapper visitMapper) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        // Validate & normalize the optional email; reject the create when it is present but invalid.
149	        if (!normalizeEmail(ownerFieldsDto)) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        // Validate & normalize the optional postcode; reject the create when it is present but
153	        // not valid for the owner's city (see normalizePostcode).
154	        if (!normalizePostcode(ownerFieldsDto)) {
155	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
156	        }
157	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
158	        // abbreviations) and store the normalized form back on the DTO so it is what gets
159	        // persisted and compared. Reject the create when the address is blank once normalized.
160	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
161	        if (canonicalAddress.isBlank()) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        ownerFieldsDto.setAddress(canonicalAddress);
165	        // Reject the create when the owner's city is already at capacity, i.e. it already
166	        // contains 50 or more owners (compared case-insensitively).
167	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
171	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
172	        if (normalizedTelephone == null) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        ownerFieldsDto.setTelephone(normalizedTelephone);
176	        // Consolidated duplicate detection. All former separate telephone, email and household
177	        // duplicate checks are now expressed through the single derived identity key
178	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
179	        // A create is rejected only when the new owner's identity collides with an existing owner's.
180	        // Because the telephone is part of the identity, two members of the same household with
181	        // different telephones no longer collide and are both allowed; only owners that share the
182	        // same normalized telephone and email are treated as the same identity.
183	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
184	        String contactIdentity = identityContact(candidate);
185	        boolean identityInUse = this.clinicService.findAllOwners().stream()
186	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
187	        if (identityInUse) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        // Household duplicate detection keyed on the deterministic householdId, derived from the
191	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
192	        // name and postcode share the same household. A second owner in an existing household is
193	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
194	        // in which case it is created as a declared household member — 'sharesHousehold' only
195	        // bypasses this block; the household link itself now follows from the computed householdId.
196	        String householdId = ownerMapper.householdId(candidate);
197	        boolean householdExists = this.clinicService.findAllOwners().stream()
198	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
199	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
200	        if (householdExists && !sharesHousehold) {
201	            return new ResponseEntity<>(HttpStatus.CONFLICT);
202	        }
203	        boolean declaredMember = householdExists && sharesHousehold;
204	        // Determine the effective registration date — the value supplied on the request, or the
205	        // server's current date when none was supplied — and roll it forward to the next business
206	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
207	        // registration date (membership-number year segment, per-day create-limit) uses this
208	        // adjusted date.
209	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
210	        if (registrationDate == null) {
211	            registrationDate = LocalDate.now();
212	        }
213	        // Reject a supplied registration date that lies in the future (later than the
214	        // server's current date): an owner cannot be registered ahead of time.
215	        else if (registrationDate.isAfter(LocalDate.now())) {
216	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
217	        }
218	        registrationDate = toBusinessDay(registrationDate);
219	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
220	        // owners have already been registered on this (adjusted) business day.
221	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
222	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
223	        }
224	        HttpHeaders headers = new HttpHeaders();
225	        Owner owner = candidate;
226	        owner.setRegistrationDate(registrationDate);
227	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
228	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
229	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
230	        owner.setCustomerCode(customerCode(owner));
231	        // Record how many existing owners already share this owner's first and last name
232	        // (compared case-insensitively) at the moment before this owner is created.
233	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
234	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
235	        // registered on this (adjusted) business day before this owner is created.
236	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
237	        // Record the size of this owner's household after this create: the number of existing
238	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
239	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
240	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
241	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
242	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
243	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
244	        // duplicate. A declared household member is an acknowledged member, not a suspected
245	        // duplicate, so it is never flagged.
246	        if (declaredMember) {
247	            owner.setPossibleDuplicate(false);
248	            owner.setPossibleDuplicateOf(null);
249	        }
250	        else {
251	            Owner softMatch = findPossibleDuplicate(owner);
252	            owner.setPossibleDuplicate(softMatch != null);
253	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
254	        }
255	        this.clinicService.saveOwner(owner);
256	        // Emit an audit line recording the new owner's id, customer code, registration date
257	        // and membership level.
258	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
259	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
260	            ownerMapper.membershipLevel(owner));
261	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
262	        headers.setLocation(UriComponentsBuilder.newInstance()
263	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
264	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
265	    }
266	
267	    /**
268	     * Validate and normalize the optional owner email in place.
269	     *
270	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
271	     * When present it must be a syntactically valid address; a valid address is
272	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
273	     * present but syntactically invalid, so the caller can reject with 400.
274	     */
275	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
276	        String email = ownerFieldsDto.getEmail();
277	        if (email == null || email.isBlank()) {
278	            ownerFieldsDto.setEmail(null);
279	            return true;
280	        }
281	        String normalized = email.trim().toLowerCase(Locale.ROOT);
282	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
283	            return false;
284	        }
285	        ownerFieldsDto.setEmail(normalized);
286	        return true;
287	    }
288	
289	    /**
290	     * Validate the optional owner postcode in place.
291	     *
292	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
293	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
294	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
295	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
296	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
297	     * when a postcode is present but malformed or out of range, so the caller can
298	     * reject with 400.
299	     */
300	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
301	        String postcode = ownerFieldsDto.getPostcode();
302	        if (postcode == null || postcode.isBlank()) {
303	            ownerFieldsDto.setPostcode(null);
304	            return true;
305	        }
306	        if (!postcode.matches("\\d{4}")) {
307	            return false;
308	        }
309	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
310	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
311	        if (range != null) {
312	            int value = Integer.parseInt(postcode);
313	            if (value < range[0] || value > range[1]) {
314	                return false;
315	            }
316	        }
317	        return true;
318	    }
319	
320	    /**
321	     * Normalize an owner address: trim, collapse each run of whitespace to a single
322	     * space, upper-case, and expand common street-type abbreviations
323	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
324	     * A {@code null} value normalizes to the empty string.
325	     */
326	    private static String normalizeAddress(String value) {
327	        if (value == null) {
328	            return "";
329	        }
330	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
331	        if (collapsed.isEmpty()) {
332	            return "";
333	        }
334	        String[] tokens = collapsed.split(" ");
335	        StringBuilder sb = new StringBuilder(collapsed.length());
336	        for (int i = 0; i < tokens.length; i++) {
337	            if (i > 0) {
338	                sb.append(' ');
339	            }
340	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
341	        }
342	        return sb.toString();
343	    }
344	
345	    /**
346	     * The contact portion of an owner's derived identity key: its normalized telephone and
347	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
348	     * without the household segment. Two owners share an identity when this value is equal;
349	     * because the telephone is part of it, members of one household with different telephones
350	     * do not collide. A {@code null} email contributes the empty string.
351	     */
352	    private static String identityContact(Owner owner) {
353	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
354	        String email = owner.getEmail() == null ? "" : owner.getEmail();
355	        return telephone + "|" + email;
356	    }
357	
358	    /**
359	     * Normalize a telephone number to E.164 form.
360	     *
361	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
362	     * explicit leading {@code '+'} and country code it is kept; otherwise the
363	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
364	     * dropped from the national digits. The result must contain 8 to 15 digits
365	     * after the {@code '+'}, and — for a recognised country calling code — exactly
366	     * the national-number length that code mandates ({@code '+61'} => 9 national
367	     * digits, {@code '+1'} => 10).
368	     *
369	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
370	     *         the input is absent or cannot form a valid E.164 number.
371	     */
372	    private static String toE164(String raw) {
373	        if (raw == null) {
374	            return null;
375	        }
376	        String trimmed = raw.trim();
377	        boolean hasCountryCode = trimmed.startsWith("+");
378	        // Strip spaces, dashes and brackets.
379	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
380	        String digits;
381	        if (hasCountryCode) {
382	            // Keep the explicit country code; drop the leading '+' for validation.
383	            digits = stripped.substring(1);
384	        } else {
385	            // No country code: assume '+61' and drop a single leading '0'.
386	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
387	            digits = "61" + national;
388	        }
389	        if (!digits.matches("\\d{8,15}")) {
390	            return null;
391	        }
392	        // For a recognised country calling code, enforce the exact national-number length it
393	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
394	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
395	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
396	                .sorted((a, b) -> b.length() - a.length()).toList()) {
397	            if (digits.startsWith(countryCode)) {
398	                int nationalLength = digits.length() - countryCode.length();
399	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
400	                    return null;
401	                }
402	                break;
403	            }
404	        }
405	        return "+" + digits;
406	    }
407	
408	    /**
409	     * Count the existing owners whose first and last name match the given names,
410	     * compared case-insensitively. Used to record an owner's namesake count at the
411	     * moment before it is created.
412	     */
413	    private int countNamesakes(String firstName, String lastName) {
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing -> existing.getFirstName() != null
416	                && existing.getFirstName().equalsIgnoreCase(firstName)
417	                && existing.getLastName() != null
418	                && existing.getLastName().equalsIgnoreCase(lastName))
419	            .count();
420	    }
421	
422	    /**
423	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
424	     * computed householdId (derived from the normalized last name and postcode). Used, together
425	     * with the owner being created, to derive the household size recorded on the owner.
426	     */
427	    private int countHouseholdMembers(Owner owner) {
428	        String householdId = ownerMapper.householdId(owner);
429	        return (int) this.clinicService.findAllOwners().stream()
430	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
431	            .count();
432	    }
433	
434	    /**
435	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
436	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
437	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
438	     * must be shared). When several existing owners match, the one with the lowest id is returned so
439	     * the result is deterministic. Returns {@code null} when there is no such match.
440	     */
441	    private Owner findPossibleDuplicate(Owner candidate) {
442	        if (candidate.getPostcode() == null) {
443	            return null;
444	        }
445	        return this.clinicService.findAllOwners().stream()
446	            .filter(existing -> existing.getLastName() != null
447	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
448	                && candidate.getPostcode().equals(existing.getPostcode())
449	                && !candidate.getTelephone().equals(existing.getTelephone()))
450	            .min(java.util.Comparator.comparing(Owner::getId))
451	            .orElse(null);
452	    }
453	
454	    /**
455	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
456	     *
457	     * <p>{@code REGION} is the region derived from the owner's postcode (see
458	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
459	     * SHA-256 of the normalized telephone concatenated with the last name
460	     * (e.g. {@code 'NSW-1A2B3C4D'}).
461	     */
462	    private String customerCode(Owner owner) {
463	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
464	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
465	        return region + "-" + hash8;
466	    }
467	
468	    /**
469	     * Derive the owner's region, preferring the postcode. The postcode is matched against
470	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
471	     * it is absent or in no known range does this fall back to the fixed city-to-region table
472	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
473	     */
474	    private static String deriveRegion(String postcode, String city) {
475	        if (postcode != null && postcode.matches("\\d{4}")) {
476	            int value = Integer.parseInt(postcode);
477	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
478	                int[] range = entry.getValue();
479	                if (value >= range[0] && value <= range[1]) {
480	                    return entry.getKey();
481	                }
482	            }
483	        }
484	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
485	    }
486	
487	    /**
488	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
489	     * bytes of {@code value}.
490	     */
491	    private static String sha256HexUpper(String value, int length) {
492	        try {
493	            byte[] digest = MessageDigest.getInstance("SHA-256")
494	                .digest(value.getBytes(StandardCharsets.UTF_8));
495	            StringBuilder sb = new StringBuilder(digest.length * 2);
496	            for (byte b : digest) {
497	                sb.append(String.format("%02X", b));
498	            }
499	            return sb.substring(0, length);
500	        }
501	        catch (NoSuchAlgorithmException e) {
502	            throw new IllegalStateException(e);
503	        }
504	    }
505	
506	    /**
507	     * Count the existing owners located in the given city, compared case-insensitively.
508	     * Used to derive the per-city 4-digit sequence in the customer code.
509	     */
510	    private int countOwnersInCity(String city) {
511	        return (int) this.clinicService.findAllOwners().stream()
512	            .filter(existing -> existing.getCity() != null
513	                && existing.getCity().equalsIgnoreCase(city))
514	            .count();
515	    }
516	
517	    /**
518	     * Count the existing owners whose registration date is the given (adjusted business) date.
519	     * Used to enforce the per-day sign-up limit.
520	     */
521	    private int countOwnersRegisteredOn(LocalDate date) {
522	        return (int) this.clinicService.findAllOwners().stream()
523	            .filter(existing -> date.equals(existing.getRegistrationDate()))
524	            .count();
525	    }
526	
527	    /**
528	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
529	     * the following Monday; a weekday is returned unchanged.
530	     */
531	    private static LocalDate toBusinessDay(LocalDate date) {
532	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
533	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
534	            date = date.plusDays(1);
535	        }
536	        return date;
537	    }
538	
539	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
540	    @Override
541	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
542	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
543	        if (currentOwner == null) {
544	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
545	        }
546	        if (!normalizeEmail(ownerFieldsDto)) {
547	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
548	        }
549	        if (!normalizePostcode(ownerFieldsDto)) {
550	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
551	        }
552	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
553	        if (normalizedTelephone == null) {
554	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
555	        }
556	        currentOwner.setAddress(ownerFieldsDto.getAddress());
557	        currentOwner.setCity(ownerFieldsDto.getCity());
558	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
559	        currentOwner.setLastName(ownerFieldsDto.getLastName());
560	        currentOwner.setTelephone(normalizedTelephone);
561	        currentOwner.setEmail(ownerFieldsDto.getEmail());
562	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
563	        this.clinicService.saveOwner(currentOwner);
564	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Transactional
569	    @Override
570	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
571	        Owner owner = this.clinicService.findOwnerById(ownerId);
572	        if (owner == null) {
573	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	        }
575	        this.clinicService.deleteOwner(owner);
576	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
577	    }
578	
579	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
580	    @Override
581	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
582	        Owner owner = this.clinicService.findOwnerById(ownerId);
583	        if (owner == null) {
584	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	        }
586	        HttpHeaders headers = new HttpHeaders();
587	        Pet pet = petMapper.toPet(petFieldsDto);
588	        owner.setId(ownerId);
589	        pet.setOwner(owner);
590	        pet.getType().setName(null);
591	        this.clinicService.savePet(pet);
592	        PetDto petDto = petMapper.toPetDto(pet);
593	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
594	            .buildAndExpand(pet.getId()).toUri());
595	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Override
600	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
601	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
602	        if (currentOwner != null) {
603	            Pet currentPet = this.clinicService.findPetById(petId);
604	            if (currentPet != null) {
605	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
606	                currentPet.setName(petFieldsDto.getName());
607	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
608	                this.clinicService.savePet(currentPet);
609	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
610	            }
611	        }
612	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
618	        HttpHeaders headers = new HttpHeaders();
619	        Visit visit = visitMapper.toVisit(visitFieldsDto);
620	        Pet pet = new Pet();
621	        pet.setId(petId);
622	        visit.setPet(pet);
623	        this.clinicService.saveVisit(visit);
624	        VisitDto visitDto = visitMapper.toVisitDto(visit);
625	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
626	            .buildAndExpand(visit.getId()).toUri());
627	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
628	    }
629	
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
634	        Owner owner = this.clinicService.findOwnerById(ownerId);
635	        if (owner != null) {
636	            Pet pet = owner.getPet(petId);
637	            if (pet != null) {
638	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
639	            }
640	        }
641	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
642	    }
643	}
